	var k := pair_key(uid)
	if not pairs.has(k):
		pairs[k] = _new_pair()
	return pairs[k]

func _new_pair() -> Dictionary:
	return {
		"bond": DEFAULT_BOND,
		"trust": DEFAULT_TRUST,
		"romance": DEFAULT_ROMANCE,
		"spouse": false,
		"last_bond_stage": 0,
		"last_romance_stage": 0,
	}

