	var k := duo_key(a, b)
	if not duos.has(k):
		duos[k] = {"bond": 0, "trust": 50, "jealousy_to": -1, "jealousy_fired": false}
	return duos[k]

func duos_for(uid: int) -> Array:
	var out: Array = []
	for k in duos:
		var parts: PackedStringArray = String(k).split(":")
